            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u00AB\u0414\u0435\u0432\u044F\u043D\u043E\u0441\u0442\u043E \u0434\u0435\u0432\u044F\u0442\u044C\u00BB \u043A\u0430\u0440\u0442\u044B \u043C\u0435\u043D\u044F\u044E\u0442 \u043E\u0431\u0449\u0443\u044E \u0441\u0443\u043C\u043C\u0443 \u0438 \u0437\u0430\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0442\u0435\u0440\u044F\u0442\u044C \u0436\u0435\u0442\u043E\u043D\u044B. \u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043F\u043E \u0434\u0435\u0432\u044F\u0442\u044C \u0436\u0435\u0442\u043E\u043D\u043E\u0432. \u0412\u044B\u0431\u044B\u0432\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u043E\u043C\u0443 \u043D\u0435 \u0445\u0432\u0430\u0442\u0438\u0442 \u0438\u0445 \u0434\u043B\u044F \u043E\u0447\u0435\u0440\u0435\u0434\u043D\u043E\u0433\u043E \u0448\u0442\u0440\u0430\u0444\u0430; \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442."),
            rule_section(:turn, "\u041A\u0430\u043A \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0445\u043E\u0434",
