              "- \u0414\u0432\u043E\u0439\u043A\u0430 \u043E\u0431\u044B\u0447\u043D\u043E \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442 \u0441\u0443\u043C\u043C\u0443. \u041D\u043E \u0447\u0451\u0442\u043D\u0443\u044E \u0441\u0443\u043C\u043C\u0443 \u0431\u043E\u043B\u044C\u0448\u0435 49 \u043E\u043D\u0430 \u0434\u0435\u043B\u0438\u0442 \u043F\u043E\u043F\u043E\u043B\u0430\u043C. \u0422\u0430\u043A, \u0438\u0437 40 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0441\u044F 80, \u0430 \u0438\u0437 60 \u2014 30. \u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439, \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u0435\u0433\u043E \u043D\u0435\u043B\u044C\u0437\u044F."),
            rule_section(:tokens, "\u041F\u043E\u0442\u0435\u0440\u044F \u0436\u0435\u0442\u043E\u043D\u043E\u0432",
              "\u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u044F \u0441\u0443\u043C\u043C\u0443, \u0441\u043B\u0435\u0434\u0438\u0442\u0435 \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u0430\u043C\u0438 33 \u0438 66:",
              "- \u0415\u0441\u043B\u0438 \u043F\u043E\u0441\u043B\u0435 \u0432\u0430\u0448\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u043F\u043E\u043B\u0443\u0447\u0438\u043B\u043E\u0441\u044C \u0440\u043E\u0432\u043D\u043E 33 \u0438\u043B\u0438 66, \u043A\u0430\u0436\u0434\u044B\u0439 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u0442\u0435\u0440\u044F\u0435\u0442 \u043F\u043E \u0436\u0435\u0442\u043E\u043D\u0443. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u0440\u0438 32 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0442\u0443\u0437\u0430 \u043A\u0430\u043A 1 \u0438 \u0441\u043D\u044F\u0442\u044C \u0436\u0435\u0442\u043E\u043D \u0441\u043E \u0432\u0441\u0435\u0445 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445.",
              "- \u0417\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u043D\u044B\u0439 \u0440\u0443\u0431\u0435\u0436, 33 \u0438\u043B\u0438 66, \u0436\u0435\u0442\u043E\u043D \u0442\u0435\u0440\u044F\u0435\u0442\u0435 \u0432\u044B. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u043E\u0434\u043D\u044F\u0432 \u0441\u0443\u043C\u043C\u0443 \u0441 30 \u0434\u043E 35, \u0432\u044B \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0451\u0442\u0435 33 \u0438 \u043F\u043E\u0442\u0435\u0440\u044F\u0435\u0442\u0435 \u043E\u0434\u0438\u043D \u0436\u0435\u0442\u043E\u043D.",
              "\u041F\u0440\u0438 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0438 \u0438\u043B\u0438 \u043F\u0440\u0435\u0432\u044B\u0448\u0435\u043D\u0438\u0438 99 \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F:",
              "- \u0420\u043E\u0432\u043D\u043E 99 \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u043F\u043E \u0434\u0432\u0430 \u0436\u0435\u0442\u043E\u043D\u0430 \u0441 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430.",
              "- \u0411\u043E\u043B\u044C\u0448\u0435 99 \u2014 \u0434\u0432\u0430 \u0436\u0435\u0442\u043E\u043D\u0430 \u0442\u0435\u0440\u044F\u0435\u0442\u0435 \u0432\u044B. \u0415\u0441\u043B\u0438 \u044D\u0442\u0438\u043C \u0436\u0435 \u0445\u043E\u0434\u043E\u043C \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043D\u043E \u0438 66, \u0441\u0443\u043C\u043C\u0430\u0440\u043D\u044B\u0439 \u0448\u0442\u0440\u0430\u0444 \u0441\u043E\u0441\u0442\u0430\u0432\u0438\u0442 \u0442\u0440\u0438 \u0436\u0435\u0442\u043E\u043D\u0430.",
              "\u041D\u043E\u0432\u044B\u0439 \u0440\u0430\u0443\u043D\u0434 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043D\u0443\u043B\u0435\u0432\u043E\u0439 \u0441\u0443\u043C\u043C\u044B \u0438 \u043D\u043E\u0432\u044B\u0445 \u043A\u0430\u0440\u0442. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 S \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0436\u0435\u0442\u043E\u043D\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u041D\u043E\u043B\u044C \u0436\u0435\u0442\u043E\u043D\u043E\u0432 \u0435\u0449\u0451 \u043D\u0435 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043F\u043E\u0440\u0430\u0436\u0435\u043D\u0438\u0435: \u0432\u044B\u0431\u044B\u0432\u0430\u044E\u0442, \u0442\u043E\u043B\u044C\u043A\u043E \u0435\u0441\u043B\u0438 \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043D\u0430 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0448\u0442\u0440\u0430\u0444. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0436\u0435\u0442\u043E\u043D \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u0434\u0430\u0442\u044C \u0438 \u043E\u0441\u0442\u0430\u0442\u044C\u0441\u044F \u0432 \u0438\u0433\u0440\u0435, \u043D\u043E \u0448\u0442\u0440\u0430\u0444 \u0432 \u0434\u0432\u0430 \u043F\u0440\u0438 \u043E\u0434\u043D\u043E\u043C \u0436\u0435\u0442\u043E\u043D\u0435 \u0443\u0436\u0435 \u0438\u0441\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0432\u0430\u0441."),
            rule_section(:variants, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438\u0433\u0440\u044B",
              "\u0414\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0430\u0440\u0442\u0438\u0438 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F:",
              "- \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0436\u0435\u0442\u043E\u043D\u043E\u0432 \u043C\u043E\u0436\u043D\u043E \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \u0438\u043B\u0438 \u0443\u043C\u0435\u043D\u044C\u0448\u0438\u0442\u044C. \u041F\u0440\u0430\u0432\u0438\u043B\u043E \u0432\u044B\u0431\u044B\u0432\u0430\u043D\u0438\u044F \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F.",
              "- \u0412\u0441\u0435\u0432\u0435\u0434\u0443\u0449\u0438\u0435 \u0431\u043E\u0442\u044B \u0432\u0438\u0434\u044F\u0442 \u043A\u0430\u0440\u0442\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u0415\u0441\u043B\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u0430, \u0442\u0430\u043A\u043E\u0433\u043E \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u0443 \u043D\u0438\u0445 \u043D\u0435\u0442.",
              "- \u041E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0448\u0442\u0440\u0430\u0444 \u0437\u0430 \u043F\u0440\u043E\u0441\u0440\u043E\u0447\u043A\u0443: \u0432\u044B \u0442\u0435\u0440\u044F\u0435\u0442\u0435 \u0436\u0435\u0442\u043E\u043D \u0438 \u0445\u043E\u0434, \u0430 \u043A\u0430\u0440\u0442\u044B \u0432 \u0440\u0443\u043A\u0435 \u0438 \u043E\u0431\u0449\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u043A\u0430\u0440\u0442\u044B.",
              "Enter: \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0442\u0443\u0437\u0430 \u043B\u0438\u0431\u043E \u0434\u0435\u0441\u044F\u0442\u043A\u0438.",
              "Escape: \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C \u0432\u044B\u0431\u043E\u0440 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F, \u043D\u0435 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044F \u043A\u0430\u0440\u0442\u0443.",
              "H: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443.",
              "C: \u0443\u0437\u043D\u0430\u0442\u044C \u043E\u0431\u0449\u0443\u044E \u0441\u0443\u043C\u043C\u0443.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0436\u0435\u0442\u043E\u043D\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "Z: \u043D\u0430\u0439\u0442\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443; \u043F\u0440\u0438 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438 \u0432\u044B\u0431\u043E\u0440\u0430 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u043D\u0435\u0439.",
              "Shift+Z: \u043D\u0430\u0439\u0442\u0438 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443; \u043F\u0440\u0438 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438 \u0432\u044B\u0431\u043E\u0440\u0430 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u043D\u0435\u0439.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434.",
              "Shift+C: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u043C\u0430\u0441\u0442\u044F\u043C; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+H: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0443; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+M: \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442.")
          ]
        end
      end
